    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking an address parameter to act as Bank by using its supportsToken
    function run(address bankAddr) public payable {
        require(bankAddr != address(0));

        // read balance before
        uint before = c.tokenBalance(address(this));

        // perform the call and capture whether it reverted
        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balance after
        uint after = c.tokenBalance(address(this));

        // General rule:
        // If the call did not revert, then before must have been 0 (hasNoBalance) and after == before + 20.
        // If the call reverted, then balance must be unchanged (after == before) or the call reverted for other reasons.
        // Expressed as a single assert combining both cases.
        assert(
            (!reverted && before == 0 && after == before + 20) ||
            (reverted && after == before)
        );
    }

    receive() external payable {}
}

