contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call airDrop and assert that if it does not revert, tokenBalance increases by 20
    // and remains non-negative. We must also respect that airDrop requires previous balance == 0
    // and that supportsToken() from msg.sender matches the token name hash.

    function run(address possiblyBank) public payable {
        require(possiblyBank != address(0));

        // read balance before
        uint before = c.tokenBalance(address(this));
        bool reverted;
        // call airDrop from this contract by asking c to treat msg.sender as this contract (it will)
        // But c.supportsToken() expects Bank(msg.sender).supportsToken() to equal keccak256("Nu Token").
        // The Bank contract provided in the environment returns that value, so we simulate calling
        // from an address that is a Bank by using the provided possiblyBank as msg.sender via a low-level call.
        // However, we cannot change msg.sender for c.airDrop since this contract is the caller. To satisfy
        // the supportsToken modifier, we ASSERT that Bank(address(this)).supportsToken() equals the expected hash
        // by performing an external call to possiblyBank.supportsToken(). The rule will only consider behavior when
        // supportsToken() of possiblyBank matches the expected hash — otherwise airDrop must revert.

        // Check external supportsToken result for the provided possiblyBank address.
        bytes32 supportHash;
        // supportsToken is external pure returning bytes32, so we can call via low-level staticcall to avoid interface
        (bool ok, bytes memory ret) = possiblyBank.staticcall(abi.encodeWithSelector(bytes4(keccak256("supportsToken()"))));
        if (ok && ret.length >= 32) {
            supportHash = abi.decode(ret, (bytes32));
        } else {
            supportHash = bytes32(0);
        }

        // attempt to call airDrop; it will use msg.sender == address(this)
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = c.tokenBalance(address(this));

        // If the provided possiblyBank reports the expected supportsToken hash, then
        // airDrop should succeed iff before == 0 and not previously locked; when it succeeds,
        // tokenBalance increases by exactly 20. If supportsToken doesn't match, airDrop must revert.
        bytes32 expected = keccak256(abi.encodePacked("Nu Token"));

        // General rule asserted:
        // - If supportHash == expected and before == 0 and not reverted then after == before + 20
        // - If supportHash != expected then the call must have reverted
        // - After successful call, balance is >= 20
        assert(
            (
                (supportHash == expected && !reverted && before == 0 && after == before + 20)
            ) || (
                (supportHash != expected && reverted)
            ) || (
                // allow the case where supportHash == expected but call reverted due to reentrancy lock or other require
                (supportHash == expected && reverted)
            ) || (
                // allow the case where before != 0: then hasNoBalance modifier requires revert
                (before != 0 && reverted)
            )
        );
    }

    receive() external payable {}
}

