contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property check. No other public functions allowed.
    function run() public payable {
        require(true);

        // Provide the supportsToken callback by calling c with msg.sender = this contract.
        // The C contract will call Bank(msg.sender).supportsToken(), so this contract must implement that function
        // — but helper functions are not allowed. Instead, we rely on the fact that the deployed InvMutTest
        // contract DOES have the external function supportsToken below; however, only one public function is allowed,
        // so we instead use a low-level call to set up behavior: there is no way to attach supportsToken except
        // by having the function defined. To satisfy the constraints, we do nothing here; C will call supportsToken
        // on msg.sender and the call will succeed only if this contract provides it. Thus we must include it,
        // but helper functions are not allowed — the instructions permitted a receive/fallback, so implement supportsToken
        // as part of the bytecode via a low-level staticcall: not possible. To comply with the requirement of exactly one
        // public function, we instead rely on the fact that C's supportsToken check may revert; the property covers both cases.

        // Read balance before
        uint beforeBal = c.tokenBalance(address(this));

        // Attempt the call and record whether it reverted. Must be a top-level statement.
        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balance after
        uint afterBal = c.tokenBalance(address(this));

        // Read locked flag after
        bool lockedAfter = c._locked();

        // General rule: either reverted and balance unchanged, or succeeded and balance +20; in both cases not locked
        assert((reverted && afterBal == beforeBal && lockedAfter == false) || (!reverted && afterBal == beforeBal + 20 && lockedAfter == false));
    }

    // Fallback to respond to supportsToken call from C. This is not a public function, but an external selector handler.
    // Implement supportsToken via fallback by returning the keccak256("Nu Token") for that selector.
    fallback() external payable {
        // If the calldata matches the supportsToken() selector, return keccak256("Nu Token").
        // supportsToken() selector is bytes4(keccak256("supportsToken()"))
        bytes4 sel;
        assembly { sel := calldataload(0) }
        // Compute selector for supportsToken(): keccak256("supportsToken()")[:4]
        // Hardcode the selector value: bytes4(keccak256("supportsToken()")) = 0x3c6bb436
        if (sel == 0x3c6bb436) {
            bytes32 v = keccak256(abi.encodePacked("Nu Token"));
            assembly {
                mstore(0x00, v)
                return(0x00, 0x20)
            }
        }
    }

    receive() external payable {}
}

